package gen

import (
	"strings"
	"text/template"
)

var structTemplate = template.Must(template.New("structCode2").Funcs(template.FuncMap{
	"firstToLower": firstToLower,
}).Parse(`
// Code generated by go-mongodb-gen; DO NOT EDIT.

package {{.Pkg}}

import (
{{- range .Imports}}
  {{.Alias}} "{{.Import}}"
{{- end}}
)

type {{.Name}}Field interface {
	{{.MongoAlias}}Field
{{- if .EqualAble}}
	{{.FilterAlias}}ComparableFilter[{{.TypePkg}}{{.Name}}]
{{- else}}
	{{.FilterAlias}}BaseFilter[{{.TypePkg}}{{.Name}}]
{{- end}}
	{{.UpdaterAlias}}BaseUpdater[{{.TypePkg}}{{.Name}}]
{{- range .Fields}}
	{{.MethodName}}F() {{.FieldName}}
{{- end}}
{{- range .Inlines}}
	{{.FiledName}}Inline
{{- end}}
}

type {{.Name}}FieldInline interface {
{{- range .Fields}}
	{{.MethodName}}F() {{.FieldName}}
{{- end}}
{{- range .Inlines}}
	{{.FiledName}}Inline
{{- end}}
}

type {{.Name|firstToLower}}Field struct {
	{{.FieldAlias}}BaseField[{{.TypePkg}}{{.Name}}]
{{- range .Inlines}}
	{{.FiledName}}Inline
{{- end}}
}

var {{.Name}}Doc = New{{.Name}}Field("")

func New{{.Name}}Field(name string) {{.Name}}Field {
	return &{{.Name|firstToLower}}Field{
		*{{.FieldAlias}}NewBaseField[{{.TypePkg}}{{.Name}}](name),
{{- range .Inlines}}
		{{.NewField}}Inline(name),
{{- end}}
	}
}

func New{{.Name}}FieldInline(name string) {{.Name}}FieldInline {
	return &{{.Name|firstToLower}}Field{
		*{{.FieldAlias}}NewBaseField[{{.TypePkg}}{{.Name}}](name),
{{- range .Inlines}}
		{{.NewField}}Inline(name),
{{- end}}
	}
}

{{- range .Fields}}

func (s *{{$.Name|firstToLower}}Field) {{.MethodName}}F() {{.FieldName}} {
	return {{.NewField}}({{$.FieldAlias}}SubField(s.FullName(), "{{.TagName}}"))
}
{{- end}}
`))

type templateData struct {
	Pkg          string
	TypePkg      string
	Name         string
	FieldAlias   string
	MongoAlias   string
	FilterAlias  string
	UpdaterAlias string
	Imports      []importTemp
	Fields       []templateField
	Inlines      []templateInline
	EqualAble    bool
}

type templateField struct {
	MethodName string
	FieldName  string
	TagName    string
	NewField   string
}

type templateInline struct {
	FiledName string
	NewField  string
}

func firstToLower(s string) string {
	if len(s) == 0 {
		return s
	}
	return strings.ToLower(s[:1]) + s[1:]
}
